export function RankClimb(props: RankClimbProps) {
  const {
    items = DEFAULT_ITEMS,
    brand = "remocn",
    from = 8,
    to = 1,
    eyebrow = "Product of the day",
    caption = "on Product Hunt",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    climbAt = T_CLIMB,
    finalSwap = LAST_DUR,
    logo,
    grain = true,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    rankClimbTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const rankEl = tl.get("rank");
  const rowsEl = tl.get("rows");
  const pushEl = tl.get("push");
  const rulesEl = tl.get("rules");
  const winEl = tl.get("win");
  const swapEls = tl.lane("Climb");
  const u = Math.min(width / 1280, height / 720);
  const th: Theme = THEMES[theme];
  const fg = ink ?? th.fg;
  const fill =
    background === "transparent" ? "transparent" : (background ?? th.bg);

  const plan = rankPlan({ items, brand, from, to, climbAt, finalSwap });
  const { others, n, start, end, K } = plan;
  const brandItem: RankItem = plan.brandItem;
  // Each overtake's row comes from the plan, its frames from the schedule.
  const swaps = plan.swaps.map((w, k) => ({
    passed: w.passed,
    s: swapEls[k].start,
    end: swapEls[k].end,
  }));
  const climbStart = swaps.length ? swaps[0].s : climbAt;
  const climbEnd = swaps.length ? swaps[swaps.length - 1].end : climbAt;
  const prog = swaps.map((w) =>
    interpolate(t, [w.s, w.end], [0, 1], { ...CLAMP, easing: EASE_SWAP }),
  );

  const initialSlot = (i: number) => (i < start ? i : i + 1);
  const brandPos = start - prog.reduce((a, b) => a + b, 0);

  const checkpoints: number[] = [];
  if (K > 0) {
    const firstPassed = others[swaps[0].passed]?.value ?? brandItem.value;
    checkpoints.push(Math.min(firstPassed * 0.9, brandItem.value * 0.9));
    swaps.forEach((w, k) => {
      const pv = others[w.passed]?.value ?? 0;
      checkpoints.push(
        k === K - 1
          ? brandItem.value
          : Math.min(pv + 14, brandItem.value - (K - k) * 10),
      );
    });
  }
  const brandValue =
    K > 0
      ? prog.reduce(
          (v, e, k) => v + (checkpoints[k + 1] - checkpoints[k]) * e,
          checkpoints[0],
        )
      : brandItem.value;

  const lift = swaps.length
    ? interpolate(
        t,
        [climbStart - 4, climbStart + 6, climbEnd - 6, climbEnd + 6],
        [0, 1, 1, 0],
        { ...CLAMP, easing: EASE_IO },
      )
    : 0;
  const T_WIN = winEl.start;
  const win = interpolate(t, [T_WIN, winEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const dim = interpolate(
    t,
    [T_WIN + winEl.beat("dimAt"), T_WIN + winEl.beat("dim")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const capIn = interpolate(
    t,
    [T_WIN + winEl.beat("captionAt"), T_WIN + winEl.beat("caption")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );

  const margin = width * 0.085;
  const listX = width * 0.5;
  const rowW = width - margin - listX;
  const rowH = Math.min(62 * u, (height * 0.7) / n);
  const listH = rowH * n;
  const listTop = (height - listH) / 2;

  const leftIn = interpolate(t, [rankEl.start, rankEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const bigSize = Math.min(232 * u, width * 0.18);
  const bigColor = interpolateColors(win, [0, 1], [th.muted, fg]);
  const push = interpolate(t, [pushEl.start, pushEl.end], [1.03, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const enterAt = (slot: number) => {
    const at = rowsEl.start + slot * rowsEl.beat("stagger");
    return interpolate(t, [at, at + rowsEl.beat("fade")], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };
  // One tilt on the wrapper that carries the whole scene covers every row,
  // number and caption under it, for as long as any of them moves.
  const moving =
    midway(interpolate(t, [pushEl.start, pushEl.end], [0, 1], CLAMP)) ||
    midway(leftIn) ||
    midway(capIn) ||
    midway(lift) ||
    prog.some(midway) ||
    Array.from({ length: n }).some((_, i) => midway(enterAt(i)));

  return (
    <AbsoluteFill style={{ background: fill, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 60% 70% at 30% 40%, ${th.stage}, transparent 75%)`,
        }}
      />
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${push})${glide(moving)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: margin,
              top: height / 2,
              transform: `translateY(-50%) translateY(${(1 - leftIn) * 12 * u}px)`,
              opacity: leftIn,
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
            }}
          >
            <span
              style={{
                fontFamily: mono,
                fontSize: 15 * u,
                fontWeight: 400,
                letterSpacing: "0.08em",
                textTransform: "uppercase",
                color: th.muted,
                whiteSpace: "nowrap",
                marginBottom: 14 * u,
              }}
            >
              {eyebrow}
            </span>
            <div
              style={{
                display: "flex",
                alignItems: "flex-start",
                marginLeft: -bigSize * 0.04,
                letterSpacing: "-0.045em",
              }}
            >
              <span
                style={{
                  position: "relative",
                  fontFamily,
                  fontWeight: 400,
                  fontSize: bigSize,
                  lineHeight: `${bigSize * 1.04}px`,
                  color: th.faint,
                  marginRight: bigSize * 0.03,
                }}
              >
                <span style={{ opacity: 1 - win }}>#</span>
                <span
                  style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    opacity: win,
                    backgroundImage: th.paint,
                    WebkitBackgroundClip: "text",
                    backgroundClip: "text",
                    WebkitTextFillColor: "transparent",
                  }}
                >
                  #
                </span>
              </span>
              <span style={{ position: "relative", display: "inline-block" }}>
                <span style={{ display: "inline-block", opacity: 1 - win }}>
                  <RollNumber
                    value={brandPos + 1}
                    min={end + 1}
                    max={start + 1}
                    size={bigSize}
                    lineHeight={1.04}
                    color={bigColor}
                    font={fontFamily}
                    weight={500}
                    blur={14 * u}
                  />
                </span>
                <span
                  style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    opacity: win,
                  }}
                >
                  <RollNumber
                    value={brandPos + 1}
                    min={end + 1}
                    max={start + 1}
                    size={bigSize}
                    lineHeight={1.04}
                    color={bigColor}
                    font={fontFamily}
                    weight={500}
                    blur={14 * u}
                    paint={th.paint}
                  />
                </span>
              </span>
            </div>
            <span
              style={{
                marginTop: 4 * u,
                fontFamily,
                fontWeight: 400,
                fontSize: 50 * u,
                letterSpacing: "-0.03em",
                color: fg,
                whiteSpace: "nowrap",
                opacity: capIn,
                transform: `translateY(${(1 - capIn) * 14 * u}px)`,
                filter:
                  capIn < 0.98 ? `blur(${(1 - capIn) * 6 * u}px)` : undefined,
              }}
            >
              {caption}
            </span>
          </div>

          <div
            style={{
              position: "absolute",
              left: listX,
              top: listTop,
              width: rowW,
              height: listH,
            }}
          >
            {Array.from({ length: n - 1 }).map((_, i) => {
              const at = rulesEl.start + i * rulesEl.beat("stagger");
              const a = interpolate(
                t,
                [at, at + rulesEl.beat("draw")],
                [0, 1],
                {
                  ...CLAMP,
                  easing: EASE_IO,
                },
              );
              return (
                <div
                  key={`h${i}`}
                  style={{
                    position: "absolute",
                    left: 0,
                    top: (i + 1) * rowH,
                    height: Math.max(1, u),
                    width: rowW * a,
                    background: th.hair,
                    opacity: 1 - 0.5 * dim,
                  }}
                />
              );
            })}
            {others.map((item, i) => {
              const slot = initialSlot(i);
              const k = swaps.findIndex((w) => w.passed === i);
              const pos = slot + (k >= 0 ? prog[k] : 0);
              const enter = enterAt(slot);
              return (
                <Row
                  key={item.label}
                  item={item}
                  pos={pos}
                  rest={slot + (k >= 0 ? 1 : 0)}
                  isBrand={false}
                  n={n}
                  rowH={rowH}
                  rowW={rowW}
                  u={u}
                  enter={enter}
                  lift={0}
                  dim={dim}
                  win={0}
                  value={item.value}
                  accent={accent}
                  th={th}
                  fg={fg}
                  fontFamily={fontFamily}
                  logo={logo}
                />
              );
            })}
            <Row
              item={brandItem}
              pos={brandPos}
              rest={end}
              isBrand
              n={n}
              rowH={rowH}
              rowW={rowW}
              u={u}
              enter={enterAt(start)}
              lift={lift}
              dim={dim}
              win={win}
              value={brandValue}
              accent={accent}
              th={th}
              fg={fg}
              fontFamily={fontFamily}
              logo={logo}
            />
          </div>
        </AbsoluteFill>
      </ScaleLayer>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 60%, ${fill} 100%)`,
          opacity: 0.55,
        }}
      />
      {grain ? <Grain opacity={th.grain} /> : null}
    </AbsoluteFill>
  );
}
